css:
#xiximg {
	background-image: url("{_root}art/xix.png");
}

@keyframes zx-slide {
	0%		{background-position: 0 0; }
	100%	{background-position: 0 -400px; }
}

body{
	background-size: 8px 400px;
	background-color: #0cc;
	animation: zx-slide 1s infinite linear;
}

#zx-cover{
	position: absolute;
	left: 0;
	right: 0;
	top: 0;
	bottom: 0;
	background-color: #ccc;
}

#right_image{
	float: right;
	width: 300px;
	height: 600px;
	background-color: #ccc;
	background-image: url("art/kriss_200x100.png");
	background-blend-mode: inherit;
	background-repeat: no-repeat;
	background-size: contain;
	background-position: center;
	image-rendering: pixelated;
	margin-left: 20px;
}

footjs:
// run some js at foot of the page maybe


var zxprogress=function(percent)
{
	var bd=document.body
	var sc=document.getElementById("body")
	var cv=document.getElementById("zx-cover")

	sc.style.filter="grayscale(1)"

	var gradient=function(c1,c2,count,rnd)
	{
		var p=100/count
		var i=0
		var j=0
		var aa=[]

		for(i=0;i<=count;i++)
		{
			aa[i]=p;
		}

		for(i=0;i<=count;i++)
		{
			var f=Math.random()*rnd
			aa[i]-=p*f
			for(j=0;j<=count;j++)
			{
				if(j!=i)
				{
					aa[j]+=p*f/(count-1)
				}
			}
		}

		var s="linear-gradient( "
		var a=0
		for(var i=0;i<count;i++)
		{
			var c=c2
			if((i%2)==0) { c=c1 }
			var b=a+aa[i]
			s+=" "+c+" "+a+"% "+b+"% "
			if(i==count-1) { s+=" ) " }
			else { s+=" , " }
			a=b
		}
		return s
	}

	var wheeeee=gradient("#0cc","#d32",16,0.1)
	var scritch=gradient("#ff3","#03f",40,0.9)

	cv.style.top="0"

	if(percent<=0)
	{
		bd.style.backgroundImage="";
	}
	else
	if(percent<100)
	{
		if(percent<4)
		{
			bd.style.backgroundImage="";
		}
		else
		if(percent<8)
		{
			bd.style.backgroundImage=wheeeee;
		}
		else
		{
			bd.style.backgroundImage=scritch;
			cv.style.top=(100*(percent-8)/92)+"%"
		}
	}
	else
	{
		sc.style.filter="none"
		bd.style.backgroundImage="";
		bd.style.backgroundColor="#bbb";
		cv.style.top="100%"
		bd.style.animation="none"

		document.getElementById('head').style.animation="fadeIn 2s forwards"
		document.getElementById('foot').style.animation="fadeIn 2s forwards"

	}
}

var start=function()
{
//	let imgurl=window.location.hash.substring(1)
//	if(imgurl!="") // can specify imgurl to display using #
//	{
//		console.log(imgurl)
//		let sc=document.getElementById("zx-screen")
//		sc.style.backgroundImage="url(\""+imgurl+"\")"
//	}
	var count=0
	var cb ; cb=function()
	{
		setTimeout(cb,1000/25)
		count++
		var percent=100*( (count-25)/250) ;
		if(percent<0){percent=0;}
		if(percent>100){percent=100;}
		zxprogress(percent)
	}
	cb()
}
start()

document.getElementById('head').style.opacity=0
document.getElementById('foot').style.opacity=0

